cd /Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature; python3 - <<'PYEOF'
import pathlib
p = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/tests/codegen/exceptions.rs')
t = p.read_text()
old = '''    assert_eq!(out.stdout, "before|");
    for expected in [
        "Fatal error: Uncaught TypeError: fwrite(): Argument #1 ($stream) must be of type resource, false given",
        "Stack trace:",
        "#0 ",
        "): fwrite(false, 'x')",
        "#1 {main}",
        "  thrown in ",
    ] {
        assert!(
            out.diagnostics.contains(expected),
            "missing `{expected}` in diagnostics={}",
            out.diagnostics
        );
    }'''
new = '''    // The harness splits php's report by KIND PREFIX: the `Fatal error:` line is a diagnostic and
    // the trace lines, which carry no prefix, stay in stdout. php prints them as one block.
    assert!(
        out.diagnostics.contains(
            "Fatal error: Uncaught TypeError: fwrite(): Argument #1 ($stream) must be of type \\
             resource, false given"
        ),
        "missing the fatal line in diagnostics={}",
        out.diagnostics
    );
    for expected in ["before|", "Stack trace:\\n#0 ", "): fwrite(false, 'x')\\n#1 {main}\\n  thrown in "] {
        assert!(
            out.stdout.contains(expected),
            "missing `{expected}` in stdout={}",
            out.stdout
        );
    }'''
assert t.count(old) == 1, 'the trace assertions were not found verbatim'
p.write_text(t.replace(old, new, 1))
print('the test follows the harness split')
